from flask import Flask, request, jsonify
from ariadne import QueryType, make_executable_schema, graphql_sync
import psycopg2
import os
import json
import logging

app = Flask(__name__)
logger = logging.getLogger(__name__)

type_defs = """
    type Query {
        user(id: ID!): User
        searchUsers(filter: String!): [User]
        getCredentialStatus: CredStatus
    }
    type User {
        id: ID!
        username: String
        email: String
        role: String
        api_key: String
    }
    type CredStatus {
        db_host: String
        last_rotated: String
        connection_pool_size: Int
    }
"""

query = QueryType()

def get_db_connection():
    """Fetch current credentials from environment (injected by sidecar)"""
    return psycopg2.connect(
        host=os.environ.get('DB_HOST', 'localhost'),
        port=os.environ.get('DB_PORT', '5432'),
        dbname=os.environ.get('DB_NAME', 'appdb'),
        user=os.environ.get('DB_USER', 'app_readonly'),
        password=os.environ.get('DB_PASSWORD', '')
    )

@query.field("user")
def resolve_user(_, info, id):
    conn = get_db_connection()
    cur = conn.cursor()
    # Parameterized - safe
    cur.execute("SELECT id, username, email, role FROM users WHERE id = %s", (id,))
    row = cur.fetchone()
    conn.close()
    if row:
        return {"id": row[0], "username": row[1], "email": row[2], "role": row[3]}
    return None

@query.field("searchUsers")
def resolve_search_users(_, info, filter):
    conn = get_db_connection()
    cur = conn.cursor()
    # VULNERABLE: Direct string interpolation in SQL from GraphQL argument
    query_str = f"SELECT id, username, email, role, api_key FROM users WHERE username LIKE '%{filter}%' OR email LIKE '%{filter}%'"
    logger.info(f"Executing search query for filter: {filter[:50]}")
    cur.execute(query_str)
    rows = cur.fetchall()
    conn.close()
    results = []
    for row in rows:
        results.append({
            "id": row[0],
            "username": row[1],
            "email": row[2],
            "role": row[3],
            "api_key": row[4]
        })
    return results

@query.field("getCredentialStatus")
def resolve_cred_status(_, info):
    return {
        "db_host": os.environ.get('DB_HOST', 'unknown'),
        "last_rotated": os.environ.get('CRED_LAST_ROTATED', 'unknown'),
        "connection_pool_size": 10
    }

schema = make_executable_schema(type_defs, query)

@app.route('/graphql', methods=['POST'])
def graphql_endpoint():
    data = request.get_json()
    if not data:
        return jsonify({"error": "No query provided"}), 400

    # Basic depth limiting (max 3 levels)
    success, result = graphql_sync(schema, data, context_value={"request": request})
    return jsonify(result), 200 if success else 400

@app.route('/health', methods=['GET'])
def health():
    try:
        conn = get_db_connection()
        conn.close()
        return jsonify({"status": "healthy", "db": "connected"}), 200
    except Exception as e:
        return jsonify({"status": "unhealthy", "error": str(e)}), 503

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
